import { useState, useEffect, useRef, useMemo } from 'react';
import type { Event } from '../../types/Event';
import { categoryForAction, colorForAction, iconForAction } from '../../components/annotate/taxonomy';
import { describeEvent, type DescribeRound } from '../../utils/describeEvent';
import { isFrameSwapped, type CornerSwapSpan } from '../../utils/cornerSwap';

interface LiveFeedProps {
  events: Event[];
  currentFrame: number;
  fps: number;
  onSeek: (time: number) => void;
  redName: string;
  blueName: string;
  redFighterId?: number | null;
  rounds?: DescribeRound[];
  cornerSwapSpans?: CornerSwapSpan[];
}

type Filter = 'all' | 'strike' | 'state' | 'grapple';

const FILTERS: { key: Filter; label: string }[] = [
  { key: 'all',    label: 'All' },
  { key: 'strike', label: 'Strikes' },
  { key: 'state',  label: 'Fight state' },
  { key: 'grapple',label: 'Grapple' },
];

function matchFilter(cat: string, filter: Filter): boolean {
  if (filter === 'all') return true;
  if (filter === 'grapple') return cat === 'grapple' || cat === 'event';
  if (filter === 'state') return cat === 'state' || cat === 'round';
  return cat === filter;
}

function fmtFrame(frame: number, fps: number): string {
  const secs = Math.max(0, Math.floor((frame - 1) / fps));
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

export default function LiveFeed({
  events, currentFrame, fps, onSeek, redName, blueName, redFighterId, rounds, cornerSwapSpans,
}: LiveFeedProps) {
  const [filter, setFilter] = useState<Filter>('all');
  const scrollRef = useRef<HTMLDivElement>(null);

  const enriched = useMemo(() => events.map(e => ({
    ...e,
    cat: categoryForAction(e.action),
    tc: fmtFrame(e.frame, fps),
    text: describeEvent(e, {
      redName, blueName, redFighterId, rounds,
      swapped: isFrameSwapped(e.frame, cornerSwapSpans ?? []),
    }),
  })), [events, fps, redName, blueName, redFighterId, rounds, cornerSwapSpans]);

  const visible = useMemo(() =>
    enriched.filter(e => e.frame <= currentFrame && matchFilter(e.cat, filter)),
    [enriched, currentFrame, filter],
  );

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [visible.length]);

  return (
    <div className="glass" style={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden' }}>
  const currentRound = spans.find(
    s => s.kind === 'round' && s.end_frame != null && currentFrame >= s.frame && currentFrame <= s.end_frame,
  )?.value
    ?? rounds.find(r => currentFrame >= r.start_frame && currentFrame <= r.end_frame)?.round_number
    ?? '-';

  const redName = selectedFight?.red_fighter_name ?? 'Red corner';
  const blueName = selectedFight?.blue_fighter_name ?? 'Blue corner';

  // Reconstructs each point event's display text on the fly (description is
  // only ever stored for fight_end) — including the swap-corrected fighter
  // name for any event whose own frame falls inside a corner_swap span, so
  // reviewing the timeline reflects a swap the moment it's marked, even for
  // strikes logged before the span existed.
  const cornerSwapSpans = useMemo(
    () => spans.filter(s => s.kind === 'corner_swap').map(s => ({ frame: s.frame, end_frame: s.end_frame })),
    [spans],
  );
  const describe = (e: Event) => describeEvent(e, {
    redName, blueName, swapped: isFrameSwapped(e.frame, cornerSwapSpans),
  });

  // ---- annotation logging state ----
  const [selected, setSelected] = useState<Corner | null>(null);
  const [toast, setToast] = useState<{ text: string; color: string; icon: string } | null>(null);
  const [flashId, setFlashId] = useState<number | null>(null);
